from student import solve as student
import base64

_ENCODED = """

"""

exec(base64.b64decode(_ENCODED).decode("utf-8"))


with open('33.txt', encoding='utf8') as f:
    filestr = f.readlines()


counter = 0
for line in filestr:
    if not line:
        continue
    line = line.strip()
    if not line:
        continue
    if solve(line) != student(line):
        counter += 1
        print(line)
        print(solve(line))
        print(student(line))
print(f'{counter=}')
print()
